"""paper/captions.md: factual caption drafts for Figures 1-5 (what is plotted, the sources, the labelling conventions), with every number computed from results/*.csv
through experiments.paper_numlib (the same recipes as paper/numbers.csv). Not paper text: no claims beyond what the plotted data show."""
import json
import os

from experiments.paper_common import PAPER
from experiments.paper_numlib import compute


def v(op, src, filt, col="loss", **extra):
    return compute(dict(op=op, source_csv=src, filter=filt, column=col, extra=json.dumps(extra) if extra else ""))


def main():
    hd = "e1e_headline.csv"
    fs = lambda c, q, att: f"condition={c};scheme=fsb;variant=fsb_base;param=100;attacker={att};q={q}"
    hp = lambda c, q, att: f"condition={c};scheme=hpb;variant=match_qbar100;attacker={att};q={q}"
    clean_emp = v("value", hd, fs("M0", 100, "emp"))
    tail_emp = [v("mean", "e1f_tailnoise_emp.csv", "q=100;variant=" + "|".join(f"tailnoise_s{s}_d{d}" for d in (1, 2, 3, 4, 5))) for s in (0.5, 1.0, 1.6)]
    full_emp = [v("mean", "e1f_tailnoise_emp.csv", "q=100;variant=" + "|".join(f"fullnoise_s{s}_d{d}" for d in (1, 2, 3, 4, 5))) for s in (0.5, 1.0, 1.6)]
    tail_est = [v("mean", "e1f_tailnoise.csv", "q=100;variant=" + "|".join(f"tailnoise_s{s}_d{d}" for d in (1, 2, 3, 4, 5))) for s in (0.5, 1.0, 1.6)]
    full_est = [v("mean", "e1f_tailnoise.csv", "q=100;variant=" + "|".join(f"fullnoise_s{s}_d{d}" for d in (1, 2, 3, 4, 5))) for s in (0.5, 1.0, 1.6)]
    es = "e1d_esterror_summary.csv"
    head_s = v("value", es, "t=1000000;group=head;method=B per-password dispersion (stored passwords)", "sigma_hat")
    tail_s = v("value", es, "t=1000000;group=tail;method=B per-password dispersion (stored passwords)", "sigma_hat")
    g = lambda c, sch, q, grp, col="contrib": v("value", "e1f_mech_groups.csv", f"condition={c};scheme={sch};q={q};group={grp}", col)
    m2x_est = v("value", "e1c_e2.csv", "condition=M2x;scheme=fsb;variant=fsb_base;param=100;attacker=est;q=100")
    t10 = {c: v("value", "e1e_tsweep_10M.csv", f"condition={c};t=10000000;q=100") for c in ("M0", "M2x")}
    t100 = {c: v("value", "e1e_tsweep.csv", f"condition={c};t=100000;q=100") for c in ("M0", "M2x")}
    L = ["# Figure captions (factual drafts)", "",
         "Generated by `experiments/paper_captions.py`; every number is computed from `results/*.csv` (recipes: `experiments/paper_numlib.py`). Not paper text.", "",
         "**Common to all figures.** est = attacker weights p^ (the deployed estimate), candidate list = top 2M of S~. emp = attacker weights from leak counts, candidate list = **all of S~** "
         "(13,125,513 passwords, no generated strings). t = 1,000,000 (histogram head size) unless stated. Loss = bucket success - baseline (no-bucket) success of the same attacker, in "
         "percentage points (pp). Error bars: sd over 5 repeats of 5,000 targets (Fig. 2: sd over 5 noise draws). Seed 2000, pool A_test. Colour-blind-safe palette; every series also has "
         "its own line style and marker, so the figures read in grey scale. Each figure exists at column width (3.3 in, `figN`) and at 7 in (`figN_wide`), as PDF and 300-dpi PNG.", "",
         "## Fig. 1 (`fig1`)", "",
         "Loss against guess budget q (log scale) for M0 (a) and M2x, passwords of length >= 8 not on the Xato blocklist (b). FSB with qbar = 100 and size-matched HPB with l = 12 "
         f"(average bucket 2,565 and 3,204 entries), against the est and emp attackers. Dotted vertical line: q = qbar. Dotted horizontal line: 5 points (drawn in both panels; it is the reference for "
         f"the est curves). At q = qbar = 100 on M0: FSB est {v('value', 'e1c_e2.csv', 'condition=M0;scheme=fsb;variant=fsb_base;param=100;attacker=est;q=100'):.2f}, "
         f"FSB emp {v('value', hd, fs('M0', 100, 'emp')):.2f}, HPB emp {v('value', hd, hp('M0', 100, 'emp')):.2f} pp; on M2x: FSB est {m2x_est:.2f}, FSB emp {v('value', hd, fs('M2x', 100, 'emp')):.2f}, "
         f"HPB emp {v('value', hd, hp('M2x', 100, 'emp')):.2f} pp. Sources: `e1c_e2.csv` (est), `e1e_headline.csv` (emp).", "",
         "## Fig. 2 (`fig2`)", "",
         "Loss at q = qbar = 100 (M0, FSB) against the noise sigma that multiplies p^ by exp(sigma z_w), for noise on every string and for noise on the non-head (tail) strings only, est and emp. "
         "Points: mean over 5 independent noise draws (salts d1..d5), bars: sd over the draws; sigma = 0 is the noise-free run (no draws). Vertical dotted lines and top-axis labels: the measured "
         f"estimator error sigma_hat on held-out data, head {head_s:.3f} and tail {tail_s:.3f} (per-password dispersion, method B, t = 1M). Dotted horizontal line: 5 points. "
         f"**Note: noise on the tail only leaves the emp attacker at the clean-estimate loss of {clean_emp:.2f} pp** (tail-only noise: {tail_emp[0]:.2f} / {tail_emp[1]:.2f} / {tail_emp[2]:.2f} at "
         f"sigma = 0.5 / 1.0 / 1.6), whereas noise on every string raises it to {full_emp[0]:.2f} / {full_emp[1]:.2f} / {full_emp[2]:.2f}. For the est attacker tail-only noise gives "
         f"{tail_est[0]:+.2f} / {tail_est[1]:+.2f} / {tail_est[2]:+.2f} and full noise {full_est[0]:+.2f} / {full_est[1]:+.2f} / {full_est[2]:+.2f}. "
         "Sources: `e1f_tailnoise.csv` (est), `e1f_tailnoise_emp.csv` (emp), `e1c_e2.csv` and `e1e_headline.csv` (sigma = 0), `e1d_esterror_summary.csv`.", "",
         "## Fig. 3 (`fig3`)", "",
         "Which targets the emp attacker gains on. Loss contribution = share of targets in the group x (attacker success - baseline success) within the group; the contributions of the three groups "
         "add up to the loss (diamond, with sd over repeats; the number above each bar is the total, pp of all targets). Groups: head = password among the top t = 1M by leak count (the histogram "
         "head); stored, not in head = in S~ but not in the head; not in S~ = no candidate (contribution 0). FSB qbar = 100 and HPB l = 12, q = 1 and q = 100, for M0 (a) and M2x (b). "
         f"On M0 at q = 100 the stored-not-in-head group contributes {g('M0', 'fsb', 100, 'tail'):+.2f} of the FSB total {g('M0', 'fsb', 100, 'total'):+.2f} (head {g('M0', 'fsb', 100, 'head'):+.2f}); "
         f"under HPB the head group contributes {g('M0', 'hpb', 100, 'head'):+.2f} of {g('M0', 'hpb', 100, 'total'):+.2f}. Source: `e1f_mech_groups.csv`.", "",
         "## Fig. 4 (`fig4`)", "",
         "emp loss at q = qbar = 100 (FSB qbar = 100) against the histogram head size t (log scale), M0 (solid) and M2x (dashed); grey dotted curve, right axis: average bucket size. "
         f"emp loss falls from {t100['M0']:.1f} (M0) / {t100['M2x']:.1f} (M2x) at t = 100k to {t10['M0']:.1f} / {t10['M2x']:.1f} at t = 10M. The est reference is **not a flat zero everywhere**: "
         f"for M0 it is 0.00 at every t that was measured (100k to 3M; `e1c_tsweep.csv`; not measured at 10M), while for M2x the only est measurement is at t = 1M and is {m2x_est:.2f} pp (open square). "
         "Sources: `e1e_tsweep.csv`, `e1e_tsweep_10M.csv` (emp), `e1c_tsweep.csv` (est, M0), `e1c_e2.csv` (est, M2x).", "",
         "## Fig. 5, appendix (`fig5`)", "",
         "emp loss at q = 100 against the average bucket size (log scale) along a qbar sweep of 1 to 3000, for the base 3-gram (add-delta), the Kneser-Ney 3-gram, and the calibrated tail "
         "estimate (cal_iso_w0.5, exploratory: cross-fitted isotonic calibration of the tail, 0.5-decade bins), M0 (a) and M2x (b). The base and Kneser-Ney curves coincide (the base is drawn with "
         "larger markers underneath). Source: `e1e_fix.csv`.", ""]
    open(os.path.join(PAPER, "captions.md"), "w").write("\n".join(L))
    print("captions written to paper/captions.md")


if __name__ == "__main__":
    main()
